"use strict";
/* ============================================================================
   EduSphere Admin — Teachers & Classes modules
   ----------------------------------------------------------------------------
   This file deliberately plugs into the existing dashboard shell. It borrows
   the shell's icons, buttons, cards, tables, forms, toasts and modal helpers;
   it does not redesign the admin area.
   ========================================================================== */
(function () {
  const teacherRoutes = new Set(["teachers/all", "teachers/add", "teachers/applications", "teachers/profiles"]);
  const classRoutes = new Set(["classes/all", "classes/add", "classes/timetable", "classes/students", "classes/teachers"]);
  let C = null;
  let root = null;

  const teacherStatusLabels = { active: "Active", inactive: "Inactive", on_leave: "On Leave", suspended: "Suspended", archived: "Archived" };
  const appStatusLabels = { pending: "Pending", under_review: "Under Review", shortlisted: "Shortlisted", interviewed: "Interviewed", accepted: "Accepted", rejected: "Rejected" };
  const trackLabels = { islamic: "Islamic", western: "Western", both: "Both" };
  const teacherRoleLabels = { class_teacher: "Class Teacher", assistant_class_teacher: "Assistant Class Teacher", subject_teacher: "Subject Teacher", substitute_teacher: "Substitute Teacher" };
  const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  function handles(route) { return teacherRoutes.has(route) || classRoutes.has(route); }
  async function render(ctx, content, route) {
    C = ctx; root = content;
    if (route === "teachers/all") return pageTeachers();
    if (route === "teachers/add") return pageAddTeacher();
    if (route === "teachers/applications") return pageTeacherApplications();
    if (route === "teachers/profiles") return pageTeacherProfiles();
    if (route === "classes/all") return pageClasses();
    if (route === "classes/add") return pageAddClass();
    if (route === "classes/timetable") return pageClassTimetable();
    if (route === "classes/students") return pageClassStudents();
    if (route === "classes/teachers") return pageClassTeachers();
  }

  const e = (v) => C.esc(v);
  const I = (name) => (C.I && C.I[name]) || "";
  const api = () => window.API;
  const fmt = (v) => C.fmtDate ? C.fmtDate(v) : (v || "—");
  const pill = (status) => C.pillFor ? C.pillFor(status) : "info";
  const opt = (rows, selected, label) => C.options(rows || [], selected, label);
  const empty = (cols, copy) => C.emptyRow(cols, copy);
  function query(obj) {
    return Object.entries(obj || {}).filter(([, v]) => v !== undefined && v !== null && v !== "").map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join("&");
  }
  function bindRoutes(scope) { scope.querySelectorAll("[data-nav-route]").forEach((b) => b.addEventListener("click", (ev) => { ev.preventDefault(); C.go(b.getAttribute("data-nav-route")); })); }
  function initials(name, fallback) { return String(name || fallback || "?").trim().split(/\s+/).map((x) => x[0]).slice(0, 2).join("").toUpperCase() || "?"; }
  function teacherAvatar(t, compact) {
    return t.photo_path ? `<img class="tc-avatar${compact ? " compact" : ""}" src="${e(t.photo_path)}" alt="">` : `<span class="tc-avatar tc-avatar-empty${compact ? " compact" : ""}">${e(initials(t.full_name, "T"))}</span>`;
  }
  function studentAvatar(s, compact) {
    return s.photo_path ? `<img class="tc-avatar${compact ? " compact" : ""}" src="${e(s.photo_path)}" alt="">` : `<span class="tc-avatar tc-avatar-empty${compact ? " compact" : ""}">${e(initials([s.first_name, s.last_name].filter(Boolean).join(" "), "S"))}</span>`;
  }
  function className(c) { return c ? `${c.name_en || ""}${c.section_arm ? " " + c.section_arm : ""}`.trim() : ""; }
  function uniqueById(rows) { const seen = new Set(); return (rows || []).filter((r) => { const id = Number(r.id); if (!id || seen.has(id)) return false; seen.add(id); return true; }); }
  function trackOptions(selected) { return Object.entries(trackLabels).map(([v, l]) => `<option value="${v}" ${v === selected ? "selected" : ""}>${l}</option>`).join(""); }
  function teacherStatusOptions(selected) { return Object.entries(teacherStatusLabels).map(([v, l]) => `<option value="${v}" ${v === selected ? "selected" : ""}>${l}</option>`).join(""); }
  function appStatusOptions(selected) { return Object.entries(appStatusLabels).map(([v, l]) => `<option value="${v}" ${v === selected ? "selected" : ""}>${l}</option>`).join(""); }
  function roleOptions(selected) { return Object.entries(teacherRoleLabels).map(([v, l]) => `<option value="${v}" ${v === selected ? "selected" : ""}>${l}</option>`).join(""); }
  function serializeForm(form) { const fd = new FormData(form); const out = Object.fromEntries(fd.entries()); return { fd, out }; }

  function teacherAssignmentSummary(t) {
    const list = (t.assignments || []).map((a) => `${a.class ? a.class.name_en : "All classes"}${a.subject ? ` · ${a.subject.name_en}` : ""}${a.role ? ` (${teacherRoleLabels[a.role] || a.role})` : ""}`);
    return list.join(", ") || "Not assigned";
  }
  function teacherSubjects(t) { return uniqueById(t.subjects || []).map((s) => s.name_en).join(", ") || "—"; }
  function teacherClasses(t) { return uniqueById(t.classes || []).map((c) => c.name_en).join(", ") || "—"; }

  /* =============================== TEACHERS =============================== */
  async function pageTeachers() {
    const base = await C.catalogue();
    let page = 1; const perPage = 12; const selected = new Set(); let currentRows = [];
    root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Teachers</div><h2>All Teachers</h2><p>Complete staff directory connected to subjects, classes, timetable and academic records.</p></div><div class="dash-actions"><button id="tcPrintTeachers" class="dash-btn dash-btn-ghost">${I("external")} Print</button><a id="tcExportTeachers" class="dash-btn dash-btn-ghost" href="${api().url("/exports/teachers.csv")}" target="_blank" rel="noopener">${I("download")} Export</a><button class="dash-btn dash-btn-primary" data-nav-route="teachers/add">${I("plus")} Add Teacher</button></div></div>
      <div id="tcTeacherStats" class="dash-stats-grid"></div>
      <div class="dash-card tc-filter-card"><div class="dash-card-pad"><div class="tc-filter-head"><div><strong>Search teachers</strong><small>Search by name, Staff ID, phone, email, position or department</small></div><button id="tcTeacherAdvanced" type="button" class="dash-btn dash-btn-ghost dash-btn-sm">Advanced filters</button></div><div class="tc-filter-grid"><div class="dash-field tc-search"><label>Search</label><input id="tcTeacherSearch" type="search" placeholder="e.g. Aisha, TCH0001 or Mathematics"></div><div class="dash-field"><label>Department</label><input id="tcTeacherDepartment" placeholder="Department"></div><div class="dash-field"><label>Subject</label><select id="tcTeacherSubject"><option value="">All subjects</option>${opt(base.subjects)}</select></div><div class="dash-field"><label>Status</label><select id="tcTeacherStatus"><option value="">All statuses</option>${teacherStatusOptions("")}</select></div></div><div id="tcTeacherMore" class="tc-filter-grid more" hidden><div class="dash-field"><label>Class</label><select id="tcTeacherClass"><option value="">All classes</option>${opt(base.classes)}</select></div><div class="dash-field"><label>Education track</label><select id="tcTeacherTrack"><option value="">All tracks</option>${trackOptions("")}</select></div><div class="dash-field"><label>Employment type</label><input id="tcTeacherEmployment" placeholder="Full-time, Part-time, Contract"></div><div class="dash-field"><label>Sort</label><select id="tcTeacherSort"><option value="name">Name</option><option value="staff">Staff ID</option><option value="department">Department</option><option value="position">Position</option><option value="employmentDate">Employment date</option><option value="status">Status</option></select></div><div class="dash-field"><label>Direction</label><select id="tcTeacherDirection"><option value="asc">Ascending</option><option value="desc">Descending</option></select></div></div></div></div>
      <div id="tcTeacherBulk" class="student-bulk-bar" hidden><strong><span data-count>0</span> selected</strong><div class="dash-actions"><select id="tcBulkTeacherStatus"><option value="">Bulk action</option>${teacherStatusOptions("")}</select><button id="tcApplyTeacherBulk" class="dash-btn dash-btn-primary dash-btn-sm">Apply</button><button id="tcClearTeacherBulk" class="dash-btn dash-btn-ghost dash-btn-sm">Clear</button></div></div>
      <div id="tcTeacherTableCard" class="dash-card"><div class="student-loading" id="tcTeacherLoading" hidden>Loading teacher records…</div><div class="dash-table-wrap"><table class="dash-table tc-directory-table"><thead><tr><th><input id="tcSelectAllTeachers" type="checkbox" aria-label="Select all teachers"></th><th>Teacher</th><th>Staff ID</th><th>Gender / Contact</th><th>Position / Department</th><th>Subjects</th><th>Classes</th><th>Track / Type</th><th>Employment</th><th>Status</th><th></th></tr></thead><tbody id="tcTeacherRows"></tbody></table></div><div id="tcTeacherCards" class="tc-mobile-cards"></div><div class="student-pagination"><span id="tcTeacherCount">—</span><span id="tcTeacherPage">Page 1</span><button id="tcTeacherPrev" class="dash-btn dash-btn-ghost dash-btn-sm">Previous</button><button id="tcTeacherNext" class="dash-btn dash-btn-ghost dash-btn-sm">Next</button></div></div>`;
    bindRoutes(root);
    const filterValues = () => ({ search: root.querySelector("#tcTeacherSearch").value.trim(), department: root.querySelector("#tcTeacherDepartment").value.trim(), subjectId: root.querySelector("#tcTeacherSubject").value, status: root.querySelector("#tcTeacherStatus").value, classId: root.querySelector("#tcTeacherClass").value, education_track: root.querySelector("#tcTeacherTrack").value, employment_type: root.querySelector("#tcTeacherEmployment").value.trim(), sort: root.querySelector("#tcTeacherSort").value, direction: root.querySelector("#tcTeacherDirection").value });
    const renderStats = (s) => { root.querySelector("#tcTeacherStats").innerHTML = `${C.statCard("teacher", s.total || 0, "Total Teachers")}${C.statCard("check", s.active || 0, "Active Teachers")}${C.statCard("book", s.islamic || 0, "Islamic Teachers", true)}${C.statCard("academic", s.western || 0, "Western Teachers")}${C.statCard("clock", s.onLeave || 0, "Teachers on Leave")}`; };
    const updateBulk = () => { const bar = root.querySelector("#tcTeacherBulk"); bar.hidden = !selected.size; bar.querySelector("[data-count]").textContent = selected.size; };
    const renderRows = (rows) => {
      currentRows = rows || [];
      const tbody = root.querySelector("#tcTeacherRows");
      tbody.innerHTML = currentRows.length ? currentRows.map((t) => `<tr><td><input class="tc-teacher-select" type="checkbox" value="${t.id}" ${selected.has(Number(t.id)) ? "checked" : ""}></td><td><div class="tc-name-cell">${teacherAvatar(t, true)}<div><strong>${e(t.full_name)}</strong><small>${e(t.email || "No email")}</small></div></div></td><td><strong>${e(t.staff_id || "—")}</strong><small>${e(t.username || "")}</small></td><td>${e(t.gender || "—")}<small>${e(t.phone || "No phone")}</small></td><td>${e(t.position || "—")}<small>${e(t.department || "—")}</small></td><td>${e(teacherSubjects(t))}</td><td>${e(teacherClasses(t))}</td><td>${e(trackLabels[t.education_track] || t.education_track || "Both")}<small>${e(t.employment_type || "—")}</small></td><td>${fmt(t.employment_date)}</td><td><span class="dash-pill ${pill(t.status)}">${e(teacherStatusLabels[t.status] || t.status)}</span></td><td><div class="dash-table-actions"><button class="dash-btn dash-btn-ghost dash-btn-sm" data-teacher-profile="${t.id}">Profile</button><button class="dash-btn dash-btn-ghost dash-btn-sm" data-teacher-edit="${t.id}">${I("edit")}</button>${t.status === "archived" ? `<button class="dash-btn dash-btn-primary dash-btn-sm" data-teacher-restore="${t.id}">Restore</button>` : `<button class="dash-btn dash-btn-danger dash-btn-sm" data-teacher-archive="${t.id}">Archive</button>`}</div></td></tr>`).join("") : empty(11, "No teachers match these filters.");
      root.querySelector("#tcTeacherCards").innerHTML = currentRows.map((t) => `<article class="tc-mobile-card"><div class="tc-card-top">${teacherAvatar(t, true)}<div><strong>${e(t.full_name)}</strong><small>${e(t.staff_id || "No Staff ID")}</small></div><span class="dash-pill ${pill(t.status)}">${e(teacherStatusLabels[t.status] || t.status)}</span></div><dl><div><dt>Position</dt><dd>${e(t.position || "—")}</dd></div><div><dt>Department</dt><dd>${e(t.department || "—")}</dd></div><div><dt>Subjects</dt><dd>${e(teacherSubjects(t))}</dd></div><div><dt>Classes</dt><dd>${e(teacherClasses(t))}</dd></div><div><dt>Contact</dt><dd>${e(t.phone || t.email || "—")}</dd></div></dl><div class="dash-actions"><button class="dash-btn dash-btn-ghost dash-btn-sm" data-teacher-profile="${t.id}">Profile</button><button class="dash-btn dash-btn-ghost dash-btn-sm" data-teacher-edit="${t.id}">${I("edit")} Edit</button></div></article>`).join("");
      root.querySelectorAll(".tc-teacher-select").forEach((box) => box.addEventListener("change", () => { const id = Number(box.value); box.checked ? selected.add(id) : selected.delete(id); updateBulk(); }));
      root.querySelectorAll("[data-teacher-profile]").forEach((b) => b.addEventListener("click", () => openTeacherProfile(Number(b.dataset.teacherProfile))));
      root.querySelectorAll("[data-teacher-edit]").forEach((b) => b.addEventListener("click", () => openTeacherEditor(Number(b.dataset.teacherEdit), () => load())));
      root.querySelectorAll("[data-teacher-archive]").forEach((b) => b.addEventListener("click", async () => { if (!confirm("Archive this teacher? Their record and documents are kept safely.")) return; try { await api().del(`/teachers/${b.dataset.teacherArchive}`); C.toast("Teacher archived.", "success"); load(); } catch (err) { C.toast(err.message || "Could not archive teacher.", "error"); } }));
      root.querySelectorAll("[data-teacher-restore]").forEach((b) => b.addEventListener("click", async () => { if (!confirm("Restore this teacher to Active status?")) return; try { await api().patch(`/teachers/${b.dataset.teacherRestore}/status`, { status: "active", reason: "Restored from archive" }); C.toast("Teacher restored.", "success"); load(); } catch (err) { C.toast(err.message || "Could not restore teacher.", "error"); } }));
      const all = root.querySelector("#tcSelectAllTeachers"); all.checked = currentRows.length > 0 && currentRows.every((t) => selected.has(Number(t.id)));
    };
    const load = async () => {
      root.querySelector("#tcTeacherLoading").hidden = false;
      try {
        const qs = query(Object.assign({}, filterValues(), { page, perPage }));
        const data = await api().get(`/teachers?${qs}`);
        renderStats(data.stats || {}); renderRows(data.teachers || []);
        root.querySelector("#tcTeacherCount").textContent = `${data.total || 0} teacher${Number(data.total) === 1 ? "" : "s"}`;
        root.querySelector("#tcTeacherPage").textContent = `Page ${data.page || page} of ${data.totalPages || 1}`;
        root.querySelector("#tcTeacherPrev").disabled = page <= 1;
        root.querySelector("#tcTeacherNext").disabled = page >= Number(data.totalPages || 1);
      } catch (err) { root.querySelector("#tcTeacherRows").innerHTML = empty(11, err.message || "Could not load teachers."); }
      finally { root.querySelector("#tcTeacherLoading").hidden = true; }
    };
    let timer; ["tcTeacherSearch", "tcTeacherDepartment", "tcTeacherSubject", "tcTeacherStatus", "tcTeacherClass", "tcTeacherTrack", "tcTeacherEmployment", "tcTeacherSort", "tcTeacherDirection"].forEach((id) => root.querySelector(`#${id}`).addEventListener(root.querySelector(`#${id}`).tagName === "INPUT" ? "input" : "change", () => { page = 1; clearTimeout(timer); timer = setTimeout(load, id.includes("Search") || id.includes("Department") || id.includes("Employment") ? 300 : 0); }));
    root.querySelector("#tcTeacherAdvanced").addEventListener("click", () => { const box = root.querySelector("#tcTeacherMore"); box.hidden = !box.hidden; root.querySelector("#tcTeacherAdvanced").textContent = box.hidden ? "Advanced filters" : "Hide advanced filters"; });
    root.querySelector("#tcTeacherPrev").addEventListener("click", () => { if (page > 1) { page--; load(); } });
    root.querySelector("#tcTeacherNext").addEventListener("click", () => { page++; load(); });
    root.querySelector("#tcSelectAllTeachers").addEventListener("change", (ev) => { currentRows.forEach((t) => ev.target.checked ? selected.add(Number(t.id)) : selected.delete(Number(t.id))); renderRows(currentRows); updateBulk(); });
    root.querySelector("#tcClearTeacherBulk").addEventListener("click", () => { selected.clear(); renderRows(currentRows); updateBulk(); });
    root.querySelector("#tcApplyTeacherBulk").addEventListener("click", async () => { const status = root.querySelector("#tcBulkTeacherStatus").value; if (!status || !selected.size) return C.toast("Choose a bulk action first.", "error"); if (!confirm(`Apply ${teacherStatusLabels[status]} to ${selected.size} teacher(s)?`)) return; try { await api().post("/teachers/bulk-status", { teacher_ids: [...selected], status }); C.toast("Bulk teacher action completed.", "success"); selected.clear(); load(); updateBulk(); } catch (err) { C.toast(err.message || "Bulk action failed.", "error"); } });
    root.querySelector("#tcPrintTeachers").addEventListener("click", () => window.print());
    root.querySelector("#tcExportTeachers").addEventListener("click", (ev) => { ev.currentTarget.href = api().url(`/exports/teachers.csv?${query(filterValues())}`); });
    await load();
  }

  function assignmentRows(container, base, assignments) {
    const host = container.querySelector("[data-assignment-host]");
    const add = (a = {}) => {
      const row = document.createElement("div"); row.className = "tc-assignment-row";
      row.innerHTML = `<select class="assign-class"><option value="">All classes</option>${opt(base.classes, a.classId || a.class_id)}</select><select class="assign-subject"><option value="">All subjects</option>${opt(base.subjects, a.subjectId || a.subject_id)}</select><select class="assign-role">${roleOptions(a.role || "subject_teacher")}</select><button type="button" class="dash-icon-btn" aria-label="Remove assignment">${I("close")}</button>`;
      row.querySelector("button").addEventListener("click", () => row.remove()); host.appendChild(row);
    };
    (assignments && assignments.length ? assignments : [{}]).forEach(add);
    container.querySelector("[data-add-assignment]").addEventListener("click", () => add());
  }
  function collectAssignments(scope) {
    return [...scope.querySelectorAll(".tc-assignment-row")].map((row) => ({ class_id: row.querySelector(".assign-class").value || null, subject_id: row.querySelector(".assign-subject").value || null, role: row.querySelector(".assign-role").value || "subject_teacher" })).filter((a) => a.class_id || a.subject_id || a.role);
  }
  function teacherPayload(form, scope) {
    const { fd, out } = serializeForm(form);
    out.full_name = [out.first_name, out.middle_name, out.last_name].filter(Boolean).join(" ").trim();
    out.available_days = fd.getAll("available_days");
    out.assignments = collectAssignments(scope || form);
    return out;
  }

  async function pageAddTeacher() {
    const base = await C.catalogue();
    root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Teachers</div><h2>Add Teacher</h2><p>Register a complete professional profile. Staff ID is generated if you leave it blank.</p></div><button class="dash-btn dash-btn-ghost" data-nav-route="teachers/all">Back to teachers</button></div>
      <form id="tcTeacherForm" class="tc-registration-form">
        ${teacherFormSections({}, base, true)}
        <div class="student-form-actions"><button type="button" class="dash-btn dash-btn-ghost" data-nav-route="teachers/all">Cancel</button><button class="dash-btn dash-btn-primary" type="submit">${I("check")} Save teacher</button></div>
      </form>`;
    bindRoutes(root); wireTeacherForm(root, base);
    root.querySelector("#tcTeacherForm").addEventListener("submit", async (ev) => {
      ev.preventDefault(); const form = ev.currentTarget; if (!form.reportValidity()) return;
      const photo = root.querySelector("#tcTeacherPhoto").files[0]; const docs = [...root.querySelector("#tcTeacherDocs").files];
      try {
        const created = await api().post("/teachers", teacherPayload(form, root));
        if (photo) { const fd = new FormData(); fd.append("photo", photo); await api().post(`/teachers/${created.id}/photo`, fd); }
        for (const file of docs.slice(0, 12)) { const fd = new FormData(); fd.append("document", file); fd.append("document_name", file.name); fd.append("document_type", "certificate"); await api().post(`/teachers/${created.id}/documents`, fd); }
        C.toast(`Teacher saved${created.staffId ? ` — ${created.staffId}` : ""}.`, "success");
        if (created.tempPassword) setTimeout(() => C.toast(`Temporary password: ${created.tempPassword}`, "success"), 250);
        C.go("teachers/profiles");
      } catch (err) { C.toast(err.message || "Could not save teacher.", "error"); }
    });
  }

  function teacherFormSections(t, base, includeFiles) {
    const selectedDays = new Set(parseList(t.available_days));
    return `<div class="dash-card"><div class="dash-card-head"><h3>Personal information</h3><span class="hint">Photo and identity</span></div><div class="dash-card-pad">${includeFiles ? `<div class="student-form-photo"><div id="tcTeacherPhotoPreview" class="student-photo-preview">${t.photo_path ? `<img src="${e(t.photo_path)}" alt="">` : `<span>${I("image")}</span>`}</div><div><label class="dash-btn dash-btn-ghost student-file-label">${I("image")} Upload photo<input id="tcTeacherPhoto" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><small class="dash-field-hint">JPG, PNG or WEBP</small></div></div>` : ""}<div class="dash-form-grid"><div class="dash-field"><label>First name <span class="req">*</span></label><input name="first_name" required maxlength="100" value="${e(t.first_name || "")}"></div><div class="dash-field"><label>Middle name</label><input name="middle_name" maxlength="100" value="${e(t.middle_name || "")}"></div><div class="dash-field"><label>Last name <span class="req">*</span></label><input name="last_name" required maxlength="100" value="${e(t.last_name || "")}"></div><div class="dash-field"><label>Gender</label><select name="gender"><option value="">Not specified</option>${["Male", "Female", "Other"].map((g) => `<option value="${g}" ${t.gender === g ? "selected" : ""}>${g}</option>`).join("")}</select></div><div class="dash-field"><label>Date of birth</label><input name="date_of_birth" type="date" value="${e(String(t.date_of_birth || "").slice(0, 10))}"></div><div class="dash-field"><label>Nationality</label><input name="nationality" value="${e(t.nationality || "Nigerian")}"></div><div class="dash-field"><label>State</label><input name="state_name" value="${e(t.state_name || "")}"></div><div class="dash-field"><label>LGA</label><input name="lga" value="${e(t.lga || "")}"></div><div class="dash-field" style="grid-column:1/-1"><label>Residential address</label><textarea name="residential_address" rows="2">${e(t.residential_address || "")}</textarea></div></div></div></div>
      <div class="dash-card"><div class="dash-card-head"><h3>Contact information</h3></div><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Phone</label><input name="phone" value="${e(t.phone || "")}"></div><div class="dash-field"><label>Alternative phone</label><input name="alternative_phone" value="${e(t.alternative_phone || "")}"></div><div class="dash-field"><label>Email</label><input name="email" type="email" value="${e(t.email || "")}"></div><div class="dash-field"><label>Emergency contact</label><input name="emergency_contact" value="${e(t.emergency_contact || "")}"></div><div class="dash-field"><label>Emergency contact relationship</label><input name="emergency_relationship" value="${e(t.emergency_relationship || "")}"></div></div></div></div>
      <div class="dash-card"><div class="dash-card-head"><h3>Professional information</h3><span class="hint">Staff ID may be auto-generated</span></div><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Staff ID</label><input name="staff_id" placeholder="Auto-generate" value="${e(t.staff_id || "")}"></div><div class="dash-field"><label>Employment date</label><input name="employment_date" type="date" value="${e(String(t.employment_date || new Date().toISOString().slice(0, 10)).slice(0, 10))}"></div><div class="dash-field"><label>Employment type</label><input name="employment_type" placeholder="Full-time, Part-time, Contract" value="${e(t.employment_type || "")}"></div><div class="dash-field"><label>Position</label><input name="position" value="${e(t.position || "")}"></div><div class="dash-field"><label>Department</label><input name="department" value="${e(t.department || "")}"></div><div class="dash-field"><label>Education track</label><select name="education_track">${trackOptions(t.education_track || "both")}</select></div><div class="dash-field"><label>Years of experience</label><input name="years_experience" type="number" min="0" max="80" value="${e(t.years_experience || 0)}"></div><div class="dash-field"><label>Status</label><select name="status">${teacherStatusOptions(t.status || "active")}</select></div><div class="dash-field" style="grid-column:1/-1"><label>Qualifications</label><textarea name="qualifications" rows="2">${e(t.qualifications || "")}</textarea></div><div class="dash-field" style="grid-column:1/-1"><label>Certifications</label><textarea name="certifications" rows="2">${e(t.certifications || "")}</textarea></div><div class="dash-field" style="grid-column:1/-1"><label>Specialization</label><input name="specialization" value="${e(t.specialization || "")}"></div></div></div></div>
      <div class="dash-card"><div class="dash-card-head"><h3>Teaching assignment</h3><span class="hint">Connected to class teachers, timetable and academic work</span></div><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Academic session</label><select name="academic_session_id"><option value="">Current / not set</option>${opt(base.sessions, t.academic_session_id, (s) => s.label)}</select></div><div class="dash-field"><label>Available periods</label><input name="available_periods" placeholder="e.g. Periods 1–4" value="${e(t.available_periods || "")}"></div></div><div class="dash-field" style="margin-top:14px"><label>Available days</label><div class="dash-check-grid compact">${days.map((d) => `<label><input type="checkbox" name="available_days" value="${d}" ${selectedDays.has(d) ? "checked" : ""}> ${d}</label>`).join("")}</div></div><div class="dash-field" style="margin-top:14px"><label>Subjects and classes</label><div data-assignment-host></div><button type="button" data-add-assignment class="dash-btn dash-btn-ghost dash-btn-sm" style="margin-top:8px">${I("plus")} Add assignment</button></div></div></div>
      <div class="dash-card"><div class="dash-card-head"><h3>Staff portal account</h3><span class="hint">Optional; generated when blank</span></div><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Username</label><input name="username" autocomplete="off" value="${e(t.username || "")}"></div><div class="dash-field"><label>${t.id ? "New password (optional)" : "Temporary password"}</label><input name="password" type="password" minlength="8" placeholder="${t.id ? "Leave unchanged" : "Auto-generate if blank"}"></div></div></div></div>
      ${includeFiles ? `<div class="dash-card"><div class="dash-card-head"><h3>Documents</h3><span class="hint">Certificates, ID, CV and other files</span></div><div class="dash-card-pad"><label class="dash-btn dash-btn-ghost student-file-label">${I("file")} Upload documents<input id="tcTeacherDocs" type="file" multiple hidden></label><div id="tcTeacherDocPreview" class="tc-doc-preview"><p class="hint">No files selected yet.</p></div></div></div>` : ""}`;
  }
  function parseList(value) { if (!value) return []; if (Array.isArray(value)) return value; try { const p = JSON.parse(value); if (Array.isArray(p)) return p; } catch (_) {} return String(value).split(",").map((x) => x.trim()).filter(Boolean); }
  function wireTeacherForm(scope, base, assignments) {
    assignmentRows(scope, base, assignments);
    const photo = scope.querySelector("#tcTeacherPhoto"); if (photo) photo.addEventListener("change", () => { const f = photo.files[0]; const prev = scope.querySelector("#tcTeacherPhotoPreview"); if (f && prev) prev.innerHTML = `<img src="${URL.createObjectURL(f)}" alt="">`; });
    const docs = scope.querySelector("#tcTeacherDocs"); if (docs) docs.addEventListener("change", () => { const list = [...docs.files].map((f) => `<div>${I("file")}<strong>${e(f.name)}</strong><small>${Math.ceil(f.size / 1024)} KB</small></div>`).join(""); scope.querySelector("#tcTeacherDocPreview").innerHTML = list || `<p class="hint">No files selected yet.</p>`; });
  }

  async function openTeacherEditor(id, done) {
    const [data, base] = await Promise.all([api().get(`/teachers/${id}`), C.catalogue()]);
    const t = data.teacher || {};
    const modal = C.openModal(`Edit teacher — ${t.full_name}`, `<form id="tcTeacherEditForm" class="tc-registration-form in-modal">${teacherFormSections(t, base, false)}<div class="dash-modal-foot" style="margin:18px -22px -20px"><button type="button" id="tcTeacherEditCancel" class="dash-btn dash-btn-ghost">Cancel</button><button class="dash-btn dash-btn-primary" type="submit">${I("check")} Save changes</button></div></form>`);
    modal.querySelector(".dash-modal").classList.add("dash-modal-wide"); wireTeacherForm(modal, base, data.assignments || []);
    modal.querySelector("#tcTeacherEditCancel").addEventListener("click", C.closeModal);
    modal.querySelector("#tcTeacherEditForm").addEventListener("submit", async (ev) => { ev.preventDefault(); try { await api().patch(`/teachers/${id}`, teacherPayload(ev.currentTarget, modal)); C.toast("Teacher profile saved.", "success"); C.closeModal(); if (done) done(); } catch (err) { C.toast(err.message || "Could not save teacher.", "error"); } });
  }

  async function openTeacherProfile(id) {
    const data = await api().get(`/teachers/${id}`); const t = data.teacher || {};
    const modal = C.openModal(`Teacher profile — ${t.full_name}`, `<div class="tc-profile-hero"><span id="tcProfileAvatar">${teacherAvatar(t)}</span><div><h3>${e(t.full_name)}</h3><p>${e(t.position || "Teacher")} · ${e(t.department || "No department")} · ${e(t.staff_id || "No Staff ID")}</p><span class="dash-pill ${pill(t.status)}">${e(teacherStatusLabels[t.status] || t.status)}</span></div><div class="dash-actions"><button id="tcProfileCard" class="dash-btn dash-btn-ghost dash-btn-sm">ID card</button><button id="tcProfileEdit" class="dash-btn dash-btn-ghost dash-btn-sm">${I("edit")} Edit</button><button id="tcProfileStatus" class="dash-btn dash-btn-ghost dash-btn-sm">Change status</button><button id="tcProfilePrint" class="dash-btn dash-btn-ghost dash-btn-sm">Print</button><a class="dash-btn dash-btn-ghost dash-btn-sm" href="${api().url(`/exports/teachers.csv?search=${encodeURIComponent(t.staff_id || t.full_name)}`)}" target="_blank">${I("download")} Export</a></div></div><div class="student-profile-tabs">${[["personal", "Personal information"], ["professional", "Professional information"], ["teaching", "Teaching"], ["academic", "Academic responsibilities"], ["achievements", "Achievements"], ["documents", "Documents"], ["communication", "Communication"]].map(([k, l]) => `<button type="button" data-t-tab="${k}">${e(l)}</button>`).join("")}</div><div id="tcTeacherIdentity"></div><div id="tcTeacherProfilePanel"></div>`);
    modal.querySelector(".dash-modal").classList.add("dash-modal-wide");
    const panel = modal.querySelector("#tcTeacherProfilePanel");
    const kv = (label, value) => `<div><b>${e(label)}</b><br>${e(value || "—")}</div>`;
    const renderTab = (tab) => {
      modal.querySelectorAll("[data-t-tab]").forEach((b) => b.classList.toggle("active", b.dataset.tTab === tab));
      if (tab === "personal") panel.innerHTML = `<div class="dash-info-grid">${kv("Date of birth", fmt(t.date_of_birth))}${kv("Gender", t.gender)}${kv("Nationality", t.nationality)}${kv("State/LGA", [t.state_name, t.lga].filter(Boolean).join(" / "))}${kv("Address", t.residential_address)}${kv("Phone", t.phone)}${kv("Alternative phone", t.alternative_phone)}${kv("Email", t.email)}${kv("Emergency contact", [t.emergency_contact, t.emergency_relationship].filter(Boolean).join(" — "))}</div>`;
      else if (tab === "professional") panel.innerHTML = `<div class="dash-info-grid">${kv("Staff ID", t.staff_id)}${kv("Position", t.position)}${kv("Department", t.department)}${kv("Education track", trackLabels[t.education_track] || t.education_track)}${kv("Employment date", fmt(t.employment_date))}${kv("Employment type", t.employment_type)}${kv("Years of experience", t.years_experience)}${kv("Specialization", t.specialization)}</div><h4 class="tc-subheading">Qualifications</h4><p class="tc-pre">${e(t.qualifications || "—")}</p><h4 class="tc-subheading">Certifications</h4><p class="tc-pre">${e(t.certifications || "—")}</p><h4 class="tc-subheading">Employment history / development</h4><p class="tc-pre">${e([t.employment_history, t.professional_development].filter(Boolean).join("\n\n") || "—")}</p>`;
      else if (tab === "teaching") panel.innerHTML = `<div class="dash-actions" style="margin-bottom:12px"><button id="tcProfileAssign" class="dash-btn dash-btn-primary dash-btn-sm">${I("plus")} Assign subject/class</button></div><div class="dash-table-wrap"><table class="dash-table"><thead><tr><th>Class</th><th>Subject</th><th>Role</th><th>Session</th><th>Periods</th></tr></thead><tbody>${(data.assignments || []).length ? data.assignments.map((a) => `<tr><td>${e(a.class ? a.class.name_en : "All classes")}</td><td>${e(a.subject ? a.subject.name_en : "All subjects")}</td><td>${e(teacherRoleLabels[a.role] || a.role)}</td><td>${e(a.sessionLabel || "—")}</td><td>${e(a.assignedPeriods || "—")}</td></tr>`).join("") : empty(5, "No assignments yet.")}</tbody></table></div><h4 class="tc-subheading">Timetable</h4><div class="dash-table-wrap"><table class="dash-table"><thead><tr><th>Day</th><th>Period</th><th>Class</th><th>Subject</th><th>Room</th></tr></thead><tbody>${(data.timetable || []).length ? data.timetable.map((s) => `<tr><td>${e(s.day)}</td><td>${e(s.period)}</td><td>${e(s.class_name || "—")}</td><td>${e(s.subject_name || "—")}</td><td>${e(s.room || "—")}</td></tr>`).join("") : empty(5, "No timetable slots yet.")}</tbody></table></div>`;
      else if (tab === "academic") { const r = data.academicResponsibilities || {}; panel.innerHTML = `<div class="dash-stats-grid">${C.statCard("book", r.lessons || 0, "Lessons")}${C.statCard("file", r.assignments || 0, "Assignments")}${C.statCard("academic", r.exams || 0, "Exams")}${C.statCard("chart", r.results || 0, "Results")}${C.statCard("calendar", r.attendanceResponsibilities || 0, "Attendance responsibilities")}</div>`; }
      else if (tab === "achievements") panel.innerHTML = `<div class="dash-info-grid">${kv("Awards", t.awards)}${kv("Training", t.training)}${kv("Certifications", t.certifications)}${kv("Professional achievements", t.achievements)}</div>`;
      else if (tab === "documents") panel.innerHTML = `<div class="dash-card"><div class="dash-card-head"><h3>Teacher documents</h3><label class="dash-btn dash-btn-primary dash-btn-sm">${I("plus")} Upload<input id="tcTeacherDocUpload" type="file" hidden></label></div><div class="dash-card-pad"><div class="tc-doc-list">${(data.documents || []).length ? data.documents.map((d) => `<div>${I("file")}<strong>${e(d.document_name)}</strong><small>${e(d.document_type || "document")} · ${Math.ceil(Number(d.file_size || 0) / 1024)} KB</small><a class="dash-btn dash-btn-ghost dash-btn-sm" href="${api().url(`/teachers/${id}/documents/${d.id}`)}" target="_blank">View</a></div>`).join("") : `<p class="hint">No documents uploaded.</p>`}</div></div></div>`;
      else panel.innerHTML = `<div class="tc-doc-list">${(data.communication || []).length ? data.communication.map((m) => `<div>${I("chat")}<strong>${e(m.scope || "message")}</strong><small>${fmt(m.created_at)}</small><p>${e(m.body || "")}</p></div>`).join("") : `<p class="hint">No communication history yet.</p>`}</div>`;
      const assign = panel.querySelector("#tcProfileAssign"); if (assign) assign.addEventListener("click", () => { C.closeModal(); openTeacherEditor(id, () => openTeacherProfile(id)); });
      const up = panel.querySelector("#tcTeacherDocUpload"); if (up) up.addEventListener("change", async () => { const file = up.files[0]; if (!file) return; const fd = new FormData(); fd.append("document", file); fd.append("document_name", file.name); try { await api().post(`/teachers/${id}/documents`, fd); C.toast("Document uploaded.", "success"); C.closeModal(); openTeacherProfile(id); } catch (err) { C.toast(err.message || "Upload failed.", "error"); } });
    };
    modal.querySelectorAll("[data-t-tab]").forEach((b) => b.addEventListener("click", () => renderTab(b.dataset.tTab)));
    modal.querySelector("#tcProfileEdit").addEventListener("click", () => { C.closeModal(); openTeacherEditor(id, () => openTeacherProfile(id)); });
    modal.querySelector("#tcProfilePrint").addEventListener("click", () => window.print());
    // Portrait, signature and ID card live on the account, not on the teaching
    // row, so an administrator can fix a picture here and the teacher can fix
    // the same field from their own portal — one value, two front doors.
    const userId = t.user_id || t.id;
    const identityHost = modal.querySelector("#tcTeacherIdentity");
    if (window.EduProfile && identityHost) {
      window.EduProfile.attachStaffIdentity(identityHost, {
        name: t.full_name,
        photoPath: t.photo_path,
        signaturePath: t.signature_path,
        userId,
      }, { cardUrl: `/documents/staff-id-card/${userId}`, api: api() });
    }
    // The hero portrait is the picture people look at, so it opens the same
    // editor as the strip below rather than a second, weaker "upload" button.
    const heroAvatar = modal.querySelector("#tcProfileAvatar");
    if (window.EduProfile && heroAvatar && userId) {
      window.EduProfile.attachAvatar(heroAvatar, {
        title: `Portrait — ${t.full_name}`,
        actionLabel: "Change photo",
        currentUrl: () => t.photo_path || "",
        savedMessage: "Portrait updated on the profile, the ID card and the portal.",
        onSave: (dataUrl) => window.EduProfile.endpoints.teacherPhoto(userId).save(dataUrl).then(() => {
          t.photo_path = dataUrl;
          heroAvatar.innerHTML = window.EduProfile.avatarHtml({ photoPath: dataUrl, name: t.full_name });
        }),
        onRemove: () => window.EduProfile.endpoints.teacherPhoto(userId).remove().then(() => {
          t.photo_path = "";
          heroAvatar.innerHTML = window.EduProfile.avatarHtml({ name: t.full_name });
        }),
      });
    }
    modal.querySelector("#tcProfileCard").addEventListener("click", () => {
      window.open(api().url(`/documents/staff-id-card/${userId}`), "_blank", "noopener");
    });
    modal.querySelector("#tcProfileStatus").addEventListener("click", () => openTeacherStatusModal(id, t.status, () => { C.closeModal(); openTeacherProfile(id); }));
    renderTab("personal");
  }

  function openTeacherStatusModal(id, current, done) {
    const modal = C.openModal("Change teacher status", `<form id="tcStatusForm"><div class="dash-field"><label>Status</label><select name="status">${teacherStatusOptions(current || "active")}</select></div><div class="dash-field" style="margin-top:12px"><label>Reason / note</label><textarea name="reason"></textarea></div><div class="dash-modal-foot" style="margin:18px -22px -20px"><button type="button" id="tcStatusCancel" class="dash-btn dash-btn-ghost">Cancel</button><button class="dash-btn dash-btn-primary">${I("check")} Update status</button></div></form>`);
    modal.querySelector("#tcStatusCancel").addEventListener("click", C.closeModal);
    modal.querySelector("#tcStatusForm").addEventListener("submit", async (ev) => { ev.preventDefault(); const fd = new FormData(ev.currentTarget); try { await api().patch(`/teachers/${id}/status`, { status: fd.get("status"), reason: fd.get("reason") }); C.toast("Teacher status updated.", "success"); C.closeModal(); if (done) done(); } catch (err) { C.toast(err.message || "Could not change status.", "error"); } });
  }

  async function pageTeacherProfiles() {
    const data = await api().get("/teachers?perPage=200");
    root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Teachers</div><h2>Teacher Profiles</h2><p>Open detailed professional profiles with teaching, documents, achievements and communication tabs.</p></div><button class="dash-btn dash-btn-primary" data-nav-route="teachers/add">${I("plus")} Add Teacher</button></div><div class="tc-profile-grid">${(data.teachers || []).length ? data.teachers.map((t) => `<button type="button" class="tc-profile-card" data-teacher-profile="${t.id}">${teacherAvatar(t)}<strong>${e(t.full_name)}</strong><small>${e(t.staff_id || "No Staff ID")}</small><span>${e(t.position || "Teacher")} · ${e(t.department || "No department")}</span><em class="dash-pill ${pill(t.status)}">${e(teacherStatusLabels[t.status] || t.status)}</em></button>`).join("") : `<div class="dash-card"><div class="dash-coming-soon"><div class="icon">${I("teacher")}</div><h3>No teacher profiles yet</h3><p>Add a teacher to create the first professional profile.</p></div></div>`}</div>`;
    bindRoutes(root); root.querySelectorAll("[data-teacher-profile]").forEach((b) => b.addEventListener("click", () => openTeacherProfile(Number(b.dataset.teacherProfile))));
  }

  /* ------------------------- Teacher applications ----------------------- */
  async function pageTeacherApplications() {
    let page = 1; const perPage = 12;
    root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Teachers</div><h2>Teacher Applications</h2><p>Recruitment queue with review history, documents and one-click conversion to staff profile.</p></div><button id="tcAddApplication" class="dash-btn dash-btn-primary">${I("plus")} Add Application</button></div><div class="dash-card tc-filter-card"><div class="dash-card-pad"><div class="tc-filter-grid"><div class="dash-field tc-search"><label>Search</label><input id="tcAppSearch" type="search" placeholder="Application ID, applicant, subject or position"></div><div class="dash-field"><label>Status</label><select id="tcAppStatus"><option value="">All statuses</option>${appStatusOptions("")}</select></div><div class="dash-field"><label>Position</label><input id="tcAppPosition" placeholder="Position"></div><div class="dash-field"><label>Education track</label><select id="tcAppTrack"><option value="">All tracks</option>${trackOptions("")}</select></div></div></div></div><div class="dash-card"><div class="student-loading" id="tcAppLoading" hidden>Loading applications…</div><div class="dash-table-wrap"><table class="dash-table"><thead><tr><th>Application</th><th>Applicant</th><th>Position</th><th>Specialization</th><th>Experience</th><th>Contact</th><th>Interview</th><th>Status</th><th></th></tr></thead><tbody id="tcAppRows"></tbody></table></div><div class="student-pagination"><span id="tcAppCount">—</span><span id="tcAppPage">Page 1</span><button id="tcAppPrev" class="dash-btn dash-btn-ghost dash-btn-sm">Previous</button><button id="tcAppNext" class="dash-btn dash-btn-ghost dash-btn-sm">Next</button></div></div>`;
    const filters = () => ({ search: root.querySelector("#tcAppSearch").value.trim(), status: root.querySelector("#tcAppStatus").value, position: root.querySelector("#tcAppPosition").value.trim(), education_track: root.querySelector("#tcAppTrack").value });
    const load = async () => { root.querySelector("#tcAppLoading").hidden = false; try { const data = await api().get(`/teachers/applications?${query(Object.assign({}, filters(), { page, perPage }))}`); root.querySelector("#tcAppRows").innerHTML = (data.applications || []).length ? data.applications.map((a) => `<tr><td><strong>${e(a.application_id)}</strong><small>${fmt(a.application_date || a.created_at)}</small></td><td><strong>${e(a.full_name)}</strong><small>${e(a.qualifications || "No qualifications entered")}</small></td><td>${e(a.position_applied || "—")}</td><td>${e(a.subjects_specialization || a.specialization || "—")}</td><td>${e(a.experience_years || 0)} year(s)</td><td>${e(a.email || "—")}<small>${e(a.phone || "")}</small></td><td>${a.interview_date ? fmt(a.interview_date) : "—"}<small>${e(a.interview_location || "")}</small></td><td><span class="dash-pill ${pill(a.status)}">${e(appStatusLabels[a.status] || a.status)}</span></td><td><button class="dash-btn dash-btn-ghost dash-btn-sm" data-app="${a.id}">${a.status === "pending" ? "Review" : "View"}</button></td></tr>`).join("") : empty(9, "No teacher applications match these filters."); root.querySelectorAll("[data-app]").forEach((b) => b.addEventListener("click", () => openTeacherApplication(Number(b.dataset.app), load))); root.querySelector("#tcAppCount").textContent = `${data.total || 0} application${Number(data.total) === 1 ? "" : "s"}`; root.querySelector("#tcAppPage").textContent = `Page ${data.page || page} of ${data.totalPages || 1}`; root.querySelector("#tcAppPrev").disabled = page <= 1; root.querySelector("#tcAppNext").disabled = page >= Number(data.totalPages || 1); } catch (err) { root.querySelector("#tcAppRows").innerHTML = empty(9, err.message || "Could not load applications."); } finally { root.querySelector("#tcAppLoading").hidden = true; } };
    let timer; ["tcAppSearch", "tcAppStatus", "tcAppPosition", "tcAppTrack"].forEach((id) => root.querySelector(`#${id}`).addEventListener(root.querySelector(`#${id}`).tagName === "INPUT" ? "input" : "change", () => { page = 1; clearTimeout(timer); timer = setTimeout(load, 250); }));
    root.querySelector("#tcAppPrev").addEventListener("click", () => { if (page > 1) { page--; load(); } }); root.querySelector("#tcAppNext").addEventListener("click", () => { page++; load(); });
    root.querySelector("#tcAddApplication").addEventListener("click", () => openApplicationEditor(null, load));
    await load();
  }

  function applicationForm(app) {
    app = app || {};
    return `<form id="tcApplicationForm"><div class="dash-form-grid"><div class="dash-field"><label>First name <span class="req">*</span></label><input name="first_name" required value="${e(app.first_name || "")}"></div><div class="dash-field"><label>Middle name</label><input name="middle_name" value="${e(app.middle_name || "")}"></div><div class="dash-field"><label>Last name <span class="req">*</span></label><input name="last_name" required value="${e(app.last_name || "")}"></div><div class="dash-field"><label>Application date</label><input name="application_date" type="date" value="${e(String(app.application_date || new Date().toISOString().slice(0, 10)).slice(0, 10))}"></div><div class="dash-field"><label>Position applied for</label><input name="position_applied" value="${e(app.position_applied || "")}"></div><div class="dash-field"><label>Education track</label><select name="education_track">${trackOptions(app.education_track || "both")}</select></div><div class="dash-field"><label>Experience (years)</label><input name="experience_years" type="number" min="0" max="80" value="${e(app.experience_years || 0)}"></div><div class="dash-field"><label>Phone</label><input name="phone" value="${e(app.phone || "")}"></div><div class="dash-field"><label>Email</label><input name="email" type="email" value="${e(app.email || "")}"></div><div class="dash-field" style="grid-column:1/-1"><label>Subjects / specialization</label><input name="subjects_specialization" value="${e(app.subjects_specialization || "")}"></div><div class="dash-field" style="grid-column:1/-1"><label>Qualifications</label><textarea name="qualifications" rows="2">${e(app.qualifications || "")}</textarea></div><div class="dash-field" style="grid-column:1/-1"><label>Certifications</label><textarea name="certifications" rows="2">${e(app.certifications || "")}</textarea></div><div class="dash-field" style="grid-column:1/-1"><label>Application / review notes</label><textarea name="message" rows="3">${e(app.message || "")}</textarea></div></div><div class="dash-field" style="margin-top:14px"><label>Documents</label><label class="dash-btn dash-btn-ghost student-file-label">${I("file")} Attach files<input id="tcApplicationDocs" type="file" multiple hidden></label><div id="tcApplicationDocPreview" class="tc-doc-preview"><p class="hint">Documents may also be uploaded after saving.</p></div></div><div class="dash-modal-foot" style="margin:18px -22px -20px"><button type="button" id="tcApplicationCancel" class="dash-btn dash-btn-ghost">Cancel</button><button class="dash-btn dash-btn-primary">${I("check")} Save application</button></div></form>`;
  }
  function openApplicationEditor(app, done) {
    const modal = C.openModal(app ? "Edit teacher application" : "Add teacher application", applicationForm(app)); modal.querySelector(".dash-modal").classList.add("dash-modal-wide");
    const docs = modal.querySelector("#tcApplicationDocs"); docs.addEventListener("change", () => { modal.querySelector("#tcApplicationDocPreview").innerHTML = [...docs.files].map((f) => `<div>${I("file")}<strong>${e(f.name)}</strong><small>${Math.ceil(f.size / 1024)} KB</small></div>`).join("") || `<p class="hint">No files selected.</p>`; });
    modal.querySelector("#tcApplicationCancel").addEventListener("click", C.closeModal);
    modal.querySelector("#tcApplicationForm").addEventListener("submit", async (ev) => { ev.preventDefault(); const payload = teacherPayload(ev.currentTarget, modal); payload.status = app ? (app.status || "pending") : "pending"; try { const saved = app ? await api().patch(`/teachers/applications/${app.id}`, payload) : await api().post("/teachers/applications", payload); const id = app ? app.id : saved.id; for (const file of [...docs.files].slice(0, 10)) { const fd = new FormData(); fd.append("document", file); fd.append("document_name", file.name); await api().post(`/teachers/applications/${id}/documents`, fd); } C.toast("Teacher application saved.", "success"); C.closeModal(); if (done) done(); } catch (err) { C.toast(err.message || "Could not save application.", "error"); } });
  }

  async function openTeacherApplication(id, done) {
    const [data, base] = await Promise.all([api().get(`/teachers/applications/${id}`), C.catalogue()]); const a = data.application;
    const modal = C.openModal(`Application — ${a.application_id}`, `<div class="tc-profile-hero"><span class="tc-avatar tc-avatar-empty">${e(initials(a.full_name, "A"))}</span><div><h3>${e(a.full_name)}</h3><p>${e(a.position_applied || "Position not set")} · ${e(trackLabels[a.education_track] || a.education_track)}</p><span class="dash-pill ${pill(a.status)}">${e(appStatusLabels[a.status] || a.status)}</span></div>${a.status === "accepted" && !a.teacher_user_id ? `<button id="tcConvertApplicationTop" class="dash-btn dash-btn-primary">${I("check")} Convert to Teacher</button>` : ""}${a.teacher_user_id ? `<button class="dash-btn dash-btn-ghost" data-open-teacher="${a.teacher_user_id}">Open Teacher Profile</button>` : ""}</div><div class="student-profile-tabs">${[["review", "Review"], ["details", "Application details"], ["documents", "Documents"], ["history", "History"], ["convert", "Convert to teacher"]].map(([k, l]) => `<button type="button" data-app-tab="${k}">${e(l)}</button>`).join("")}</div><div id="tcApplicationPanel"></div>`);
    modal.querySelector(".dash-modal").classList.add("dash-modal-wide"); const panel = modal.querySelector("#tcApplicationPanel");
    const render = (tab) => {
      modal.querySelectorAll("[data-app-tab]").forEach((b) => b.classList.toggle("active", b.dataset.appTab === tab));
      if (tab === "review") panel.innerHTML = `<form id="tcReviewApplication"><div class="dash-form-grid"><div class="dash-field"><label>Status</label><select name="status">${appStatusOptions(a.status)}</select></div><div class="dash-field"><label>Interview date</label><input name="interview_date" type="date" value="${e(String(a.interview_date || "").slice(0, 10))}"></div><div class="dash-field"><label>Interview time</label><input name="interview_time" type="time" value="${e(a.interview_time || "")}"></div><div class="dash-field"><label>Interview location</label><input name="interview_location" value="${e(a.interview_location || "")}"></div><div class="dash-field" style="grid-column:1/-1"><label>Interview information / panel</label><input name="interview_panel" value="${e(a.interview_panel || "")}"></div><div class="dash-field" style="grid-column:1/-1"><label>Review notes</label><textarea name="review_note" rows="3">${e(a.review_note || "")}</textarea></div><div class="dash-field" style="grid-column:1/-1"><label>Request additional information</label><textarea name="requested_information" rows="2">${e(a.requested_information || "")}</textarea></div></div><div class="dash-actions" style="margin-top:14px"><button class="dash-btn dash-btn-primary">${I("check")} Save review</button><button type="button" data-status="shortlisted" class="dash-btn dash-btn-ghost">Shortlist</button><button type="button" data-status="interviewed" class="dash-btn dash-btn-ghost">Interviewed</button><button type="button" data-status="accepted" class="dash-btn dash-btn-ghost">Accept</button><button type="button" data-status="rejected" class="dash-btn dash-btn-danger">Reject</button></div></form>`;
      else if (tab === "details") panel.innerHTML = `<div class="dash-info-grid"><div><b>Contact details</b><br>${e(a.email || "—")}<br>${e(a.phone || "—")}</div><div><b>Specialization</b><br>${e(a.subjects_specialization || a.specialization || "—")}</div><div><b>Qualifications</b><br>${e(a.qualifications || "—")}</div><div><b>Experience</b><br>${e(a.experience_years || 0)} year(s)</div><div><b>Application note</b><br>${e(a.message || "—")}</div><div><b>Interview</b><br>${a.interview_date ? fmt(a.interview_date) : "—"} ${e(a.interview_time || "")}<br>${e(a.interview_location || "")}</div></div>`;
      else if (tab === "documents") panel.innerHTML = `<div class="dash-card"><div class="dash-card-head"><h3>Documents</h3><label class="dash-btn dash-btn-primary dash-btn-sm">${I("plus")} Upload<input id="tcAppDocUpload" type="file" hidden></label></div><div class="dash-card-pad"><div class="tc-doc-list">${(data.documents || []).length ? data.documents.map((d) => `<div>${I("file")}<strong>${e(d.document_name)}</strong><small>${e(d.document_type || "document")} · ${Math.ceil(Number(d.file_size || 0) / 1024)} KB</small><a class="dash-btn dash-btn-ghost dash-btn-sm" href="${api().url(`/teachers/applications/${id}/documents/${d.id}`)}" target="_blank">View</a></div>`).join("") : `<p class="hint">No documents uploaded.</p>`}</div></div></div>`;
      else if (tab === "history") panel.innerHTML = `<div class="tc-doc-list">${(data.history || []).length ? data.history.map((h) => `<div>${I("clock")}<strong>${e(appStatusLabels[h.to_status] || h.to_status)}</strong><small>${fmt(h.created_at)}</small><p>${e(h.note || "")}</p></div>`).join("") : `<p class="hint">No application history yet.</p>`}</div>`;
      else panel.innerHTML = a.teacher_user_id ? `<p class="dash-info-line">This application has already been converted to a teacher profile.</p>` : `<form id="tcConvertApplication"><p class="dash-info-line">Applicant information, qualifications and documents will be transferred automatically. Only optional login credentials and assignments can be set here.</p><div class="dash-form-grid" style="margin-top:14px"><div class="dash-field"><label>Staff ID</label><input name="staff_id" placeholder="Auto-generate"></div><div class="dash-field"><label>Username</label><input name="username" placeholder="Auto-generate"></div><div class="dash-field"><label>Temporary password</label><input name="password" type="password" minlength="8" placeholder="Auto-generate"></div><div class="dash-field"><label>Employment date</label><input name="employment_date" type="date" value="${new Date().toISOString().slice(0, 10)}"></div></div><div class="dash-field" style="margin-top:14px"><label>Initial assignments</label><div data-assignment-host></div><button type="button" data-add-assignment class="dash-btn dash-btn-ghost dash-btn-sm" style="margin-top:8px">${I("plus")} Add assignment</button></div><button class="dash-btn dash-btn-primary" style="margin-top:14px">${I("check")} Convert to Teacher</button></form>`;
      const review = panel.querySelector("#tcReviewApplication"); if (review) { review.addEventListener("submit", async (ev) => { ev.preventDefault(); const fd = new FormData(review); try { await api().patch(`/teachers/applications/${id}`, Object.fromEntries(fd.entries())); C.toast("Application review saved.", "success"); C.closeModal(); if (done) done(); } catch (err) { C.toast(err.message || "Could not save review.", "error"); } }); panel.querySelectorAll("[data-status]").forEach((b) => b.addEventListener("click", async () => { try { await api().patch(`/teachers/applications/${id}`, { status: b.dataset.status, review_note: review.querySelector("[name=review_note]").value, requested_information: review.querySelector("[name=requested_information]").value }); C.toast("Application updated.", "success"); C.closeModal(); if (done) done(); } catch (err) { C.toast(err.message || "Could not update application.", "error"); } })); }
      const upload = panel.querySelector("#tcAppDocUpload"); if (upload) upload.addEventListener("change", async () => { const file = upload.files[0]; if (!file) return; const fd = new FormData(); fd.append("document", file); fd.append("document_name", file.name); try { await api().post(`/teachers/applications/${id}/documents`, fd); C.toast("Document uploaded.", "success"); C.closeModal(); openTeacherApplication(id, done); } catch (err) { C.toast(err.message || "Upload failed.", "error"); } });
      const convert = panel.querySelector("#tcConvertApplication"); if (convert) { assignmentRows(panel, base, []); convert.addEventListener("submit", async (ev) => { ev.preventDefault(); const fd = new FormData(convert); const payload = Object.fromEntries(fd.entries()); payload.assignments = collectAssignments(panel); try { const out = await api().post(`/teachers/applications/${id}/convert`, payload); C.toast(`Converted to teacher${out.staffId ? ` — ${out.staffId}` : ""}.`, "success"); if (out.tempPassword) setTimeout(() => C.toast(`Temporary password: ${out.tempPassword}`, "success"), 250); C.closeModal(); C.go("teachers/profiles"); } catch (err) { C.toast(err.message || "Could not convert application.", "error"); } }); }
    };
    modal.querySelectorAll("[data-app-tab]").forEach((b) => b.addEventListener("click", () => render(b.dataset.appTab))); const top = modal.querySelector("#tcConvertApplicationTop"); if (top) top.addEventListener("click", () => render("convert")); const open = modal.querySelector("[data-open-teacher]"); if (open) open.addEventListener("click", () => { C.closeModal(); openTeacherProfile(Number(open.dataset.openTeacher)); }); render("review");
  }

  /* =============================== CLASSES =============================== */
  async function pageClasses() {
    const base = await C.catalogue(); let page = 1; const perPage = 12;
    root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Classes</div><h2>All Classes</h2><p>Shared Islamic, Western and dual-track class directory connected to students, teachers and timetable.</p></div><div class="dash-actions"><button id="tcPrintClasses" class="dash-btn dash-btn-ghost">${I("external")} Print</button><a id="tcExportClasses" class="dash-btn dash-btn-ghost" href="${api().url("/exports/classes.csv")}" target="_blank">${I("download")} Export</a><button class="dash-btn dash-btn-primary" data-nav-route="classes/add">${I("plus")} Add Class</button></div></div><div id="tcClassStats" class="dash-stats-grid"></div><div class="dash-card tc-filter-card"><div class="dash-card-pad"><div class="tc-filter-grid"><div class="dash-field tc-search"><label>Search</label><input id="tcClassSearch" type="search" placeholder="Class name, code, level or arm"></div><div class="dash-field"><label>Education track</label><select id="tcClassTrack"><option value="">All tracks</option>${trackOptions("")}</select></div><div class="dash-field"><label>Program</label><input id="tcClassProgram" placeholder="Program"></div><div class="dash-field"><label>Level</label><input id="tcClassLevel" placeholder="Primary 1, JSS 1, Hifz"></div><div class="dash-field"><label>Session</label><select id="tcClassSession"><option value="">All sessions</option>${opt(base.sessions, null, (s) => s.label)}</select></div><div class="dash-field"><label>Status</label><select id="tcClassStatus"><option value="">All active/inactive</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="archived">Archived</option></select></div></div></div></div><div class="dash-card"><div class="student-loading" id="tcClassLoading" hidden>Loading classes…</div><div class="dash-table-wrap"><table class="dash-table tc-directory-table"><thead><tr><th>Class</th><th>Code</th><th>Track</th><th>Program</th><th>Level / Arm</th><th>Session / Term</th><th>Students</th><th>Class Teacher</th><th>Assistant</th><th>Subjects</th><th>Status</th><th></th></tr></thead><tbody id="tcClassRows"></tbody></table></div><div id="tcClassCards" class="tc-mobile-cards"></div><div class="student-pagination"><span id="tcClassCount">—</span><span id="tcClassPage">Page 1</span><button id="tcClassPrev" class="dash-btn dash-btn-ghost dash-btn-sm">Previous</button><button id="tcClassNext" class="dash-btn dash-btn-ghost dash-btn-sm">Next</button></div></div>`;
    bindRoutes(root); const filters = () => ({ search: root.querySelector("#tcClassSearch").value.trim(), education_track: root.querySelector("#tcClassTrack").value, program: root.querySelector("#tcClassProgram").value.trim(), level: root.querySelector("#tcClassLevel").value.trim(), sessionId: root.querySelector("#tcClassSession").value, status: root.querySelector("#tcClassStatus").value });
    const renderStats = (s) => { root.querySelector("#tcClassStats").innerHTML = `${C.statCard("classes", s.total || 0, "Total Classes")}${C.statCard("check", s.active || 0, "Active Classes")}${C.statCard("book", s.islamic || 0, "Islamic Track", true)}${C.statCard("academic", s.western || 0, "Western Track")}${C.statCard("trash", s.archived || 0, "Archived")}`; };
    const load = async () => { root.querySelector("#tcClassLoading").hidden = false; try { const data = await api().get(`/classes?${query(Object.assign({}, filters(), { page, perPage }))}`); renderStats(data.stats || {}); const rows = data.classes || []; root.querySelector("#tcClassRows").innerHTML = rows.length ? rows.map((c) => `<tr><td><strong>${e(c.name_en)}</strong>${c.name_ar ? `<small class="dash-ar">${e(c.name_ar)}</small>` : ""}</td><td>${e(c.class_code || "—")}</td><td>${e(trackLabels[c.education_track] || c.education_track)}</td><td>${e(c.program || "—")}</td><td>${e(c.level_name || "—")}<small>${e(c.section_arm || "")}</small></td><td>${e(c.session_label || "—")}<small>${e(c.term_name || "")}</small></td><td>${e(c.student_count || 0)}</td><td>${e(c.class_teacher_name || "—")}</td><td>${e(c.assistant_teacher_name || "—")}</td><td>${e(c.subject_count || 0)}</td><td><span class="dash-pill ${pill(c.status)}">${e(c.status)}</span></td><td><div class="dash-table-actions"><button class="dash-btn dash-btn-ghost dash-btn-sm" data-class-view="${c.id}">View</button><button class="dash-btn dash-btn-ghost dash-btn-sm" data-class-edit="${c.id}">${I("edit")}</button><button class="dash-btn dash-btn-ghost dash-btn-sm" data-class-students="${c.id}">Students</button><button class="dash-btn dash-btn-ghost dash-btn-sm" data-class-teachers="${c.id}">Teachers</button>${c.status === "archived" ? `<button class="dash-btn dash-btn-primary dash-btn-sm" data-class-restore="${c.id}">Restore</button>` : `<button class="dash-btn dash-btn-danger dash-btn-sm" data-class-archive="${c.id}">Archive</button>`}</div></td></tr>`).join("") : empty(12, "No classes match these filters."); root.querySelector("#tcClassCards").innerHTML = rows.map((c) => `<article class="tc-mobile-card"><div class="tc-card-top"><span class="tc-avatar tc-avatar-empty compact">${I("classes")}</span><div><strong>${e(c.name_en)}</strong><small>${e(c.class_code || "No code")}</small></div><span class="dash-pill ${pill(c.status)}">${e(c.status)}</span></div><dl><div><dt>Track</dt><dd>${e(trackLabels[c.education_track] || c.education_track)}</dd></div><div><dt>Program</dt><dd>${e(c.program || "—")}</dd></div><div><dt>Students</dt><dd>${e(c.student_count || 0)}</dd></div><div><dt>Teacher</dt><dd>${e(c.class_teacher_name || "—")}</dd></div></dl><div class="dash-actions"><button class="dash-btn dash-btn-ghost dash-btn-sm" data-class-view="${c.id}">View</button><button class="dash-btn dash-btn-ghost dash-btn-sm" data-class-edit="${c.id}">Edit</button></div></article>`).join(""); root.querySelectorAll("[data-class-view]").forEach((b) => b.addEventListener("click", () => openClassProfile(Number(b.dataset.classView)))); root.querySelectorAll("[data-class-edit]").forEach((b) => b.addEventListener("click", () => openClassEditor(Number(b.dataset.classEdit), load))); root.querySelectorAll("[data-class-students]").forEach((b) => b.addEventListener("click", () => { C.state.cache.classStudentsId = Number(b.dataset.classStudents); C.go("classes/students"); })); root.querySelectorAll("[data-class-teachers]").forEach((b) => b.addEventListener("click", () => { C.state.cache.classTeachersId = Number(b.dataset.classTeachers); C.go("classes/teachers"); })); root.querySelectorAll("[data-class-archive]").forEach((b) => b.addEventListener("click", async () => { if (!confirm("Archive this class? Student records remain intact.")) return; try { await api().del(`/classes/${b.dataset.classArchive}`); C.toast("Class archived.", "success"); load(); } catch (err) { C.toast(err.message || "Could not archive class.", "error"); } })); root.querySelectorAll("[data-class-restore]").forEach((b) => b.addEventListener("click", async () => { if (!confirm("Restore this class to Active status?")) return; try { await api().patch(`/classes/${b.dataset.classRestore}`, { status: "active" }); C.toast("Class restored.", "success"); load(); } catch (err) { C.toast(err.message || "Could not restore class.", "error"); } })); root.querySelector("#tcClassCount").textContent = `${data.total || 0} class${Number(data.total) === 1 ? "" : "es"}`; root.querySelector("#tcClassPage").textContent = `Page ${data.page || page} of ${data.totalPages || 1}`; root.querySelector("#tcClassPrev").disabled = page <= 1; root.querySelector("#tcClassNext").disabled = page >= Number(data.totalPages || 1); } catch (err) { root.querySelector("#tcClassRows").innerHTML = empty(12, err.message || "Could not load classes."); } finally { root.querySelector("#tcClassLoading").hidden = true; } };
    let timer; ["tcClassSearch", "tcClassTrack", "tcClassProgram", "tcClassLevel", "tcClassSession", "tcClassStatus"].forEach((id) => root.querySelector(`#${id}`).addEventListener(root.querySelector(`#${id}`).tagName === "INPUT" ? "input" : "change", () => { page = 1; clearTimeout(timer); timer = setTimeout(load, 250); }));
    root.querySelector("#tcClassPrev").addEventListener("click", () => { if (page > 1) { page--; load(); } }); root.querySelector("#tcClassNext").addEventListener("click", () => { page++; load(); }); root.querySelector("#tcPrintClasses").addEventListener("click", () => window.print()); root.querySelector("#tcExportClasses").addEventListener("click", (ev) => { ev.currentTarget.href = api().url(`/exports/classes.csv?${query(filters())}`); }); await load();
  }

  async function pageAddClass() { const [base, teachers] = await Promise.all([C.catalogue(), api().get("/teachers?perPage=200")]); root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Classes</div><h2>Add Class</h2><p>Create Islamic, Western, dual-track or custom classes in one shared class database.</p></div><button class="dash-btn dash-btn-ghost" data-nav-route="classes/all">Back to classes</button></div><form id="tcClassForm" class="tc-registration-form">${classFormSections({}, base, teachers.teachers || [])}<div class="student-form-actions"><button type="button" class="dash-btn dash-btn-ghost" data-nav-route="classes/all">Cancel</button><button class="dash-btn dash-btn-primary">${I("check")} Create class</button></div></form>`; bindRoutes(root); root.querySelector("#tcClassForm").addEventListener("submit", async (ev) => { ev.preventDefault(); try { const payload = classPayload(ev.currentTarget); await api().post("/classes", payload); C.toast("Class created.", "success"); C.go("classes/all"); } catch (err) { C.toast(err.message || "Could not create class.", "error"); } }); }
  function classFormSections(c, base, teachers) { const terms = (base.sessions || []).flatMap((s) => (s.terms || []).map((t) => Object.assign({ session_label: s.label }, t))); return `<div class="dash-card"><div class="dash-card-head"><h3>Class information</h3><span class="hint">Custom classes are supported</span></div><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Class name <span class="req">*</span></label><input name="name_en" required list="tcClassExamples" value="${e(c.name_en || "")}"><datalist id="tcClassExamples"><option value="Arabic Primary 1"><option value="Arabic Primary 2"><option value="Qur'an Class"><option value="Hifz Class"><option value="Arabic Secondary 1"><option value="Primary 1"><option value="Primary 2"><option value="JSS 1"><option value="JSS 2"><option value="SS 1"><option value="SS 2"></datalist></div><div class="dash-field"><label>Class code</label><input name="class_code" placeholder="Auto from name" value="${e(c.class_code || "")}"></div><div class="dash-field"><label>Arabic name</label><input name="name_ar" dir="rtl" value="${e(c.name_ar || "")}"></div><div class="dash-field"><label>Education track</label><select name="education_track">${trackOptions(c.education_track || "both")}</select></div><div class="dash-field"><label>Program</label><input name="program" value="${e(c.program || "")}"></div><div class="dash-field"><label>Level</label><input name="level" value="${e(c.level_name || c.level || "")}"></div><div class="dash-field"><label>Section / arm</label><input name="section_arm" value="${e(c.section_arm || "")}"></div><div class="dash-field"><label>Academic session</label><select name="session_id"><option value="">Not set</option>${opt(base.sessions, c.session_id, (s) => s.label)}</select></div><div class="dash-field"><label>Term / semester</label><select name="term_id"><option value="">Not set</option>${opt(terms, c.term_id, (t) => `${t.session_label} — ${t.name_en}`)}</select></div><div class="dash-field"><label>Class teacher</label><select name="class_teacher_id"><option value="">Unassigned</option>${opt(teachers, c.class_teacher_id, (t) => `${t.full_name} (${t.staff_id || t.username})`)}</select></div><div class="dash-field"><label>Assistant teacher</label><select name="assistant_teacher_id"><option value="">Unassigned</option>${opt(teachers, c.assistant_teacher_id, (t) => `${t.full_name} (${t.staff_id || t.username})`)}</select></div><div class="dash-field"><label>Maximum student capacity</label><input name="max_capacity" type="number" min="0" value="${e(c.max_capacity || "")}"></div><div class="dash-field"><label>Status</label><select name="status"><option value="active" ${c.status !== "inactive" ? "selected" : ""}>Active</option><option value="inactive" ${c.status === "inactive" ? "selected" : ""}>Inactive</option></select></div><div class="dash-field" style="grid-column:1/-1"><label>Description</label><textarea name="description" rows="3">${e(c.description || "")}</textarea></div></div></div></div><div class="dash-card"><div class="dash-card-head"><h3>Subjects</h3><span class="hint">Optional; timetable also links subjects automatically</span></div><div class="dash-card-pad"><div class="dash-check-grid">${(base.subjects || []).length ? base.subjects.map((s) => `<label><input type="checkbox" name="subject_ids" value="${s.id}" ${(c.subjects || []).some((x) => Number(x.id) === Number(s.id)) ? "checked" : ""}> ${e(s.name_en)}</label>`).join("") : "No subjects yet — add them in Subjects."}</div></div></div>`; }
  function classPayload(form) { const fd = new FormData(form); const out = Object.fromEntries(fd.entries()); out.subject_ids = fd.getAll("subject_ids"); return out; }
  async function openClassEditor(id, done) { const [data, base, teachers] = await Promise.all([api().get(`/classes/${id}`), C.catalogue(), api().get("/teachers?perPage=200")]); const modal = C.openModal(`Edit class — ${data.class.name_en}`, `<form id="tcClassEditForm" class="tc-registration-form in-modal">${classFormSections(data.class, base, teachers.teachers || [])}<div class="dash-modal-foot" style="margin:18px -22px -20px"><button type="button" id="tcClassEditCancel" class="dash-btn dash-btn-ghost">Cancel</button><button class="dash-btn dash-btn-primary">${I("check")} Save class</button></div></form>`); modal.querySelector(".dash-modal").classList.add("dash-modal-wide"); modal.querySelector("#tcClassEditCancel").addEventListener("click", C.closeModal); modal.querySelector("#tcClassEditForm").addEventListener("submit", async (ev) => { ev.preventDefault(); try { await api().patch(`/classes/${id}`, classPayload(ev.currentTarget)); C.toast("Class saved.", "success"); C.closeModal(); if (done) done(); } catch (err) { C.toast(err.message || "Could not save class.", "error"); } }); }
  async function openClassProfile(id) { const data = await api().get(`/classes/${id}`); const c = data.class; const modal = C.openModal(`Class — ${c.name_en}`, `<div class="tc-profile-hero"><span class="tc-avatar tc-avatar-empty">${I("classes")}</span><div><h3>${e(c.name_en)}</h3><p>${e(c.class_code || "No code")} · ${e(trackLabels[c.education_track] || c.education_track)} · ${e(c.program || "No program")}</p><span class="dash-pill ${pill(c.status)}">${e(c.status)}</span></div><div class="dash-actions"><button id="tcOpenClassEdit" class="dash-btn dash-btn-ghost dash-btn-sm">${I("edit")} Edit</button><button id="tcOpenClassStudents" class="dash-btn dash-btn-ghost dash-btn-sm">Students</button><button id="tcOpenClassTeachers" class="dash-btn dash-btn-ghost dash-btn-sm">Teachers</button><button id="tcOpenClassTimetable" class="dash-btn dash-btn-ghost dash-btn-sm">Timetable</button></div></div><div class="dash-info-grid">${[["Academic session", c.session_label], ["Current term/semester", c.term_name], ["Level", c.level_name], ["Section/arm", c.section_arm], ["Students", data.students.length], ["Subjects", (c.subjects || []).map((s) => s.name_en).join(", ")], ["Class teacher", c.class_teacher_name], ["Assistant teacher", c.assistant_teacher_name], ["Capacity", c.max_capacity], ["Description", c.description]].map(([l, v]) => `<div><b>${e(l)}</b><br>${e(v || "—")}</div>`).join("")}</div>`); modal.querySelector(".dash-modal").classList.add("dash-modal-wide"); modal.querySelector("#tcOpenClassEdit").addEventListener("click", () => { C.closeModal(); openClassEditor(id); }); modal.querySelector("#tcOpenClassStudents").addEventListener("click", () => { C.closeModal(); C.state.cache.classStudentsId = id; C.go("classes/students"); }); modal.querySelector("#tcOpenClassTeachers").addEventListener("click", () => { C.closeModal(); C.state.cache.classTeachersId = id; C.go("classes/teachers"); }); modal.querySelector("#tcOpenClassTimetable").addEventListener("click", () => { C.closeModal(); C.state.cache.timetableClassId = id; C.go("classes/timetable"); }); }

  async function pageClassTimetable() { const [base, teacherData] = await Promise.all([C.catalogue(), api().get("/teachers?perPage=200")]); const selected = C.state.cache.timetableClassId || (base.classes[0] && base.classes[0].id) || ""; const terms = (base.sessions || []).flatMap((s) => (s.terms || []).map((t) => Object.assign({ session_label: s.label }, t))); root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Classes</div><h2>Class Timetable</h2><p>Create and edit class schedules. Conflicts for teacher, class period and classroom are rejected by the server.</p></div></div><div class="dash-card"><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Class</label><select id="tcTimetableClass"><option value="">Select class</option>${opt(base.classes, selected)}</select></div><div class="dash-field"><label>Academic term / semester</label><select id="tcTimetableTerm"><option value="">Current term</option>${opt(terms, "", (t) => `${t.session_label} — ${t.name_en}`)}</select></div></div><div id="tcTimetableEditor" style="margin-top:18px"></div></div></div>`; const load = async () => { const classId = root.querySelector("#tcTimetableClass").value; const termId = root.querySelector("#tcTimetableTerm").value; const out = root.querySelector("#tcTimetableEditor"); if (!classId) { out.innerHTML = `<p class="hint">Choose a class to manage its timetable.</p>`; return; } C.state.cache.timetableClassId = Number(classId); try { const grid = await api().get(`/timetable?classId=${encodeURIComponent(classId)}${termId ? `&termId=${encodeURIComponent(termId)}` : ""}`); const found = (d, p) => (grid.slots || []).find((s) => s.day === d && Number(s.period) === Number(p)) || {}; out.innerHTML = `<div class="dash-table-wrap"><table class="dash-table dash-timetable-edit tc-timetable-table"><thead><tr><th>Day / Period</th><th>Time</th><th>Subject</th><th>Teacher</th><th>Classroom / room</th></tr></thead><tbody>${(grid.days || []).flatMap((d) => (grid.periods || []).map((p) => { const s = found(d, p.period); return `<tr data-day="${d}" data-period="${p.period}"><td><strong>${d}</strong><small>Period ${p.period}</small></td><td><input class="slot-start" type="time" value="${e(s.startTime || p.start || "")}"> <input class="slot-end" type="time" value="${e(s.endTime || p.end || "")}"></td><td><select class="slot-subject"><option value="">— No class —</option>${opt(base.subjects, s.subjectId)}</select></td><td><select class="slot-teacher"><option value="">—</option>${opt(teacherData.teachers || [], s.teacherId, (t) => t.full_name)}</select></td><td><input class="slot-room" value="${e(s.room || "")}" placeholder="Room / classroom"></td></tr>`; })).join("")}</tbody></table></div><div class="tc-mobile-timetable">${(grid.days || []).map((d) => `<section><h4>${d}</h4>${(grid.periods || []).map((p) => { const s = found(d, p.period); return `<div><b>P${p.period}</b><span>${e(s.subjectEn || "Free")}</span><small>${e(s.teacherName || "")} ${s.room ? "· " + e(s.room) : ""}</small></div>`; }).join("")}</section>`).join("")}</div><div class="dash-actions" style="margin-top:16px"><button id="tcSaveTimetable" class="dash-btn dash-btn-primary">${I("check")} Save timetable</button><a class="dash-btn dash-btn-ghost" href="${api().url(`/timetable/print?classId=${encodeURIComponent(classId)}${termId ? `&termId=${encodeURIComponent(termId)}` : ""}`)}" target="_blank">${I("external")} Print timetable</a><a class="dash-btn dash-btn-ghost" href="${api().url(`/exports/timetable.csv?classId=${encodeURIComponent(classId)}${termId ? `&termId=${encodeURIComponent(termId)}` : ""}`)}" target="_blank">${I("download")} Export</a></div>`; out.querySelector("#tcSaveTimetable").addEventListener("click", async () => { const slots = [...out.querySelectorAll("tbody tr")].map((row) => ({ day: row.dataset.day, period: Number(row.dataset.period), startTime: row.querySelector(".slot-start").value, endTime: row.querySelector(".slot-end").value, subjectId: row.querySelector(".slot-subject").value || null, teacherId: row.querySelector(".slot-teacher").value || null, room: row.querySelector(".slot-room").value })).filter((s) => s.subjectId || s.teacherId || s.room); try { const saved = await api().put("/timetable", { classId: Number(classId), termId: termId ? Number(termId) : undefined, slots }); C.toast(`${saved.saved} timetable slot(s) saved.`, "success"); load(); } catch (err) { C.toast(err.message || "Could not save timetable.", "error"); } }); } catch (err) { out.innerHTML = `<p class="dash-error">${e(err.message || "Could not load timetable.")}</p>`; } }; root.querySelector("#tcTimetableClass").addEventListener("change", load); root.querySelector("#tcTimetableTerm").addEventListener("change", load); if (selected) load(); }

  async function pageClassStudents() { const data = await api().get("/classes?perPage=200"); const classes = data.classes || []; const selected = C.state.cache.classStudentsId || (classes[0] && classes[0].id) || ""; const selectedSet = new Set(); root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Classes</div><h2>Class Students</h2><p>Roster for the selected class. Students are assigned here without duplicating records.</p></div></div><div class="dash-card"><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Class</label><select id="tcRosterClass"><option value="">Select class</option>${opt(classes, selected)}</select></div></div><div id="tcRosterOut" style="margin-top:16px"></div></div></div>`; const load = async () => { const classId = root.querySelector("#tcRosterClass").value; const out = root.querySelector("#tcRosterOut"); if (!classId) { out.innerHTML = ""; return; } C.state.cache.classStudentsId = Number(classId); selectedSet.clear(); try { const r = await api().get(`/classes/${classId}/students`); out.innerHTML = `<div class="dash-stats-grid">${C.statCard("users", r.stats.total, "Total Students")}${C.statCard("users", r.stats.male, "Male")}${C.statCard("users", r.stats.female, "Female")}${C.statCard("check", r.stats.active, "Active")}${C.statCard("close", r.stats.inactive, "Inactive")}</div><div class="dash-actions" style="margin-bottom:12px"><button id="tcAddClassStudent" class="dash-btn dash-btn-primary">${I("plus")} Add student</button><button id="tcBulkTransfer" class="dash-btn dash-btn-ghost">Bulk transfer</button><a class="dash-btn dash-btn-ghost" href="${api().url(`/exports/students.csv?classId=${classId}`)}" target="_blank">${I("download")} Export</a><button id="tcPrintRegister" class="dash-btn dash-btn-ghost">Print class register</button></div><div class="dash-table-wrap"><table class="dash-table"><thead><tr><th><input id="tcRosterAll" type="checkbox"></th><th>Student</th><th>Student ID</th><th>Admission No.</th><th>Gender</th><th>Attendance</th><th>Performance</th><th>Fee status</th><th>Status</th><th></th></tr></thead><tbody>${(r.students || []).length ? r.students.map((s) => `<tr><td><input class="tc-roster-select" type="checkbox" value="${s.id}"></td><td><div class="tc-name-cell">${studentAvatar(s, true)}<strong>${e([s.first_name, s.last_name].filter(Boolean).join(" "))}</strong></div></td><td>${e(s.student_code || "—")}</td><td>${e(s.admission_no || "—")}</td><td>${e(s.gender || "—")}</td><td>${e(s.attendance_status || "unmarked")}</td><td>${s.academic_performance ? e(Number(s.academic_performance).toFixed(1) + "%") : "—"}</td><td><span class="dash-pill ${s.fee_status === "paid" ? "ok" : "warn"}">${e(s.fee_status)}</span></td><td><span class="dash-pill ${pill(s.status)}">${e(s.status)}</span></td><td><div class="dash-table-actions"><button class="dash-btn dash-btn-ghost dash-btn-sm" data-student-profile="${s.id}">Profile</button><button class="dash-btn dash-btn-danger dash-btn-sm" data-remove-student="${s.id}">Remove</button></div></td></tr>`).join("") : empty(10, "This class has no students yet.")}</tbody></table></div>`; out.querySelectorAll(".tc-roster-select").forEach((box) => box.addEventListener("change", () => { box.checked ? selectedSet.add(Number(box.value)) : selectedSet.delete(Number(box.value)); })); const all = out.querySelector("#tcRosterAll"); if (all) all.addEventListener("change", () => { out.querySelectorAll(".tc-roster-select").forEach((box) => { box.checked = all.checked; box.checked ? selectedSet.add(Number(box.value)) : selectedSet.delete(Number(box.value)); }); }); out.querySelector("#tcAddClassStudent").addEventListener("click", () => openAddStudentToClass(classId, load)); out.querySelector("#tcBulkTransfer").addEventListener("click", () => openBulkTransfer(classId, classes, [...selectedSet], load)); out.querySelector("#tcPrintRegister").addEventListener("click", () => window.print()); out.querySelectorAll("[data-remove-student]").forEach((b) => b.addEventListener("click", async () => { if (!confirm("Remove this student from the class? Their student record remains safe.")) return; try { await api().del(`/classes/${classId}/students/${b.dataset.removeStudent}`); C.toast("Student removed from class.", "success"); load(); } catch (err) { C.toast(err.message || "Could not remove student.", "error"); } })); out.querySelectorAll("[data-student-profile]").forEach((b) => b.addEventListener("click", () => { C.state.cache.profileStudentId = Number(b.dataset.studentProfile); C.go("students/profiles"); })); } catch (err) { out.innerHTML = `<p class="dash-error">${e(err.message || "Could not load roster.")}</p>`; } }; root.querySelector("#tcRosterClass").addEventListener("change", load); if (selected) load(); }
  async function openAddStudentToClass(classId, done) { const data = await api().get("/students?perPage=200"); const modal = C.openModal("Add student to class", `<form id="tcAddStudentClassForm"><div class="dash-field"><label>Student</label><select name="student_id" required><option value="">Choose student</option>${opt(data.students || [], null, (s) => `${s.first_name} ${s.last_name} — ${s.admission_no}`)}</select></div><div class="dash-field" style="margin-top:12px"><label>Note</label><input name="notes" placeholder="Optional placement note"></div><div class="dash-modal-foot" style="margin:18px -22px -20px"><button type="button" id="tcCancelAddStudent" class="dash-btn dash-btn-ghost">Cancel</button><button class="dash-btn dash-btn-primary">${I("check")} Add student</button></div></form>`); modal.querySelector("#tcCancelAddStudent").addEventListener("click", C.closeModal); modal.querySelector("#tcAddStudentClassForm").addEventListener("submit", async (ev) => { ev.preventDefault(); const fd = new FormData(ev.currentTarget); try { await api().post(`/classes/${classId}/students`, Object.fromEntries(fd.entries())); C.toast("Student assigned to class.", "success"); C.closeModal(); done(); } catch (err) { C.toast(err.message || "Could not assign student.", "error"); } }); }
  function openBulkTransfer(fromClassId, classes, studentIds, done) { const modal = C.openModal("Bulk transfer students", `<form id="tcBulkTransferForm"><p class="dash-info-line">${studentIds.length} selected student(s) will remain the same records and only their class assignment changes.</p><div class="dash-field" style="margin-top:14px"><label>Target class</label><select name="to_class_id" required><option value="">Choose class</option>${opt(classes.filter((c) => Number(c.id) !== Number(fromClassId)))}</select></div><div class="dash-field" style="margin-top:12px"><label>Note</label><textarea name="notes"></textarea></div><div class="dash-modal-foot" style="margin:18px -22px -20px"><button type="button" id="tcCancelBulkTransfer" class="dash-btn dash-btn-ghost">Cancel</button><button class="dash-btn dash-btn-primary">${I("check")} Transfer</button></div></form>`); modal.querySelector("#tcCancelBulkTransfer").addEventListener("click", C.closeModal); modal.querySelector("#tcBulkTransferForm").addEventListener("submit", async (ev) => { ev.preventDefault(); if (!studentIds.length) return C.toast("Select students first.", "error"); const fd = new FormData(ev.currentTarget); try { await api().post(`/classes/${fromClassId}/students/transfer`, { student_ids: studentIds, to_class_id: fd.get("to_class_id"), notes: fd.get("notes") }); C.toast("Students transferred.", "success"); C.closeModal(); done(); } catch (err) { C.toast(err.message || "Could not transfer students.", "error"); } }); }

  async function pageClassTeachers() { const [classData, teacherData, base] = await Promise.all([api().get("/classes?perPage=200"), api().get("/teachers?perPage=200"), C.catalogue()]); const classes = classData.classes || []; const selected = C.state.cache.classTeachersId || (classes[0] && classes[0].id) || ""; root.innerHTML = `<div class="dash-page-head"><div><div class="dash-crumb">Classes</div><h2>Class Teachers</h2><p>All teachers assigned to the selected class and their subject responsibilities.</p></div></div><div class="dash-card"><div class="dash-card-pad"><div class="dash-form-grid"><div class="dash-field"><label>Class</label><select id="tcTeacherClassSelect"><option value="">Select class</option>${opt(classes, selected)}</select></div></div><div id="tcClassTeacherOut" style="margin-top:16px"></div></div></div>`; const load = async () => { const classId = root.querySelector("#tcTeacherClassSelect").value; const out = root.querySelector("#tcClassTeacherOut"); if (!classId) { out.innerHTML = ""; return; } C.state.cache.classTeachersId = Number(classId); try { const data = await api().get(`/classes/${classId}/teachers`); out.innerHTML = `<div class="dash-actions" style="margin-bottom:12px"><button id="tcAssignTeacher" class="dash-btn dash-btn-primary">${I("plus")} Assign teacher</button><button id="tcViewClassTimetable" class="dash-btn dash-btn-ghost">View timetable</button></div><div class="dash-table-wrap"><table class="dash-table"><thead><tr><th>Teacher</th><th>Staff ID</th><th>Subject</th><th>Role</th><th>Contact</th><th>Assigned periods</th><th>Status</th><th></th></tr></thead><tbody>${(data.teachers || []).length ? data.teachers.map((t) => `<tr><td><div class="tc-name-cell">${teacherAvatar(t, true)}<strong>${e(t.full_name)}</strong></div></td><td>${e(t.staff_id || "—")}</td><td>${e(t.subject ? t.subject.name_en : "All subjects")}</td><td>${e(teacherRoleLabels[t.role] || t.role)}</td><td>${e(t.phone || t.email || "—")}</td><td>${e(t.assigned_periods || "—")}</td><td><span class="dash-pill ${pill(t.status)}">${e(t.status)}</span></td><td><div class="dash-table-actions"><button class="dash-btn dash-btn-ghost dash-btn-sm" data-open-teacher="${t.id}">Profile</button><button class="dash-btn dash-btn-danger dash-btn-sm" data-remove-assignment="${t.assignment_id}">Remove</button></div></td></tr>`).join("") : empty(8, "No teachers assigned to this class.")}</tbody></table></div>`; out.querySelector("#tcAssignTeacher").addEventListener("click", () => openAssignTeacher(classId, teacherData.teachers || [], base.subjects || [], load)); out.querySelector("#tcViewClassTimetable").addEventListener("click", () => { C.state.cache.timetableClassId = Number(classId); C.go("classes/timetable"); }); out.querySelectorAll("[data-open-teacher]").forEach((b) => b.addEventListener("click", () => openTeacherProfile(Number(b.dataset.openTeacher)))); out.querySelectorAll("[data-remove-assignment]").forEach((b) => b.addEventListener("click", async () => { if (!confirm("Remove this teacher assignment?")) return; try { await api().del(`/classes/${classId}/teachers/${b.dataset.removeAssignment}`); C.toast("Assignment removed.", "success"); load(); } catch (err) { C.toast(err.message || "Could not remove assignment.", "error"); } })); } catch (err) { out.innerHTML = `<p class="dash-error">${e(err.message || "Could not load class teachers.")}</p>`; } }; root.querySelector("#tcTeacherClassSelect").addEventListener("change", load); if (selected) load(); }
  function openAssignTeacher(classId, teachers, subjects, done) { const modal = C.openModal("Assign teacher to class", `<form id="tcAssignTeacherForm"><div class="dash-form-grid"><div class="dash-field"><label>Teacher</label><select name="teacher_id" required><option value="">Choose teacher</option>${opt(teachers, null, (t) => `${t.full_name} (${t.staff_id || t.username})`)}</select></div><div class="dash-field"><label>Subject</label><select name="subject_id"><option value="">All subjects / class role</option>${opt(subjects)}</select></div><div class="dash-field"><label>Role</label><select name="role">${roleOptions("subject_teacher")}</select></div><div class="dash-field"><label>Assigned periods</label><input name="assigned_periods" placeholder="e.g. Mon P1, Tue P3"></div><div class="dash-field" style="grid-column:1/-1"><label>Notes</label><textarea name="notes"></textarea></div></div><div class="dash-modal-foot" style="margin:18px -22px -20px"><button type="button" id="tcCancelAssignTeacher" class="dash-btn dash-btn-ghost">Cancel</button><button class="dash-btn dash-btn-primary">${I("check")} Assign teacher</button></div></form>`); modal.querySelector("#tcCancelAssignTeacher").addEventListener("click", C.closeModal); modal.querySelector("#tcAssignTeacherForm").addEventListener("submit", async (ev) => { ev.preventDefault(); const fd = new FormData(ev.currentTarget); try { await api().post(`/classes/${classId}/teachers`, Object.fromEntries(fd.entries())); C.toast("Teacher assigned.", "success"); C.closeModal(); done(); } catch (err) { C.toast(err.message || "Could not assign teacher.", "error"); } }); }

  window.BelloTeacherClasses = { handles, render };
})();
